    'generic' => [
      'e01' => ['title'=>'Battery Communication Fault','severity'=>'high','description'=>'Controller cannot communicate reliably with the battery management system (BMS).','what'=>'Your controller is not receiving stable data from the battery/BMS, so it may limit or disable assist to protect the system.','causes'=>['Battery not fully seated or connector pins contaminated','Damaged harness between battery cradle and controller','BMS protective shutdown or firmware mismatch','Water ingress/corrosion in high-current connectors'],'symptoms'=>['Motor assist cuts out or never engages','Display shows battery bars jumping or resets','Error appears after bumps/vibration (intermittent contact)'],'fix'=>['Power cycle the bike (turn off, wait 10s, turn on).','Check battery connector seating and cleanliness.','Ensure battery firmware is up to date (OEM tool).','If persists, contact dealer — battery module diagnosis required.'],'rideability'=>'stop','rideabilityGuidance'=>'Avoid riding. If assist cuts out unexpectedly it can be unsafe, and repeated attempts can worsen connector damage.','urgency'=>'immediate','urgencyGuidance'=>'If cleaning/reseating doesn\'t fix it, you likely need dealer diagnostics (battery cradle, BMS, or controller).','source'=>'Generic BMS/Controller guidance'],
      'e02' => ['title'=>'Motor Overcurrent / Overload','severity'=>'high','description'=>'Motor draws excessive current — could be heavy load, binding, or wiring short.','what'=>'The controller detected current draw beyond safe limits and may shut down assist to prevent damage to wiring and power electronics.','causes'=>['Riding at high assist on steep climbs or starting in a high gear','Wheel/drivetrain binding (brake rub, debris, bent rotor)','Damaged motor phase wiring or connector short','Internal motor fault (windings) or controller failure'],'symptoms'=>['Assist cuts out under load (hills/acceleration)','Motor feels jerky or makes unusual noises','Error returns immediately when you apply power'],'fix'=>['Stop riding and check for debris caught in the wheel or drivetrain.','Inspect motor connectors and wiring for damage or corrosion.','Lower pedal assist level and test on flat ground.','If error repeats, have motor tested at a service center.'],'rideability'=>'stop','rideabilityGuidance'=>'Stop using assist. You can pedal unassisted if the bike rolls freely; do not keep forcing power through the motor.','urgency'=>'immediate','urgencyGuidance'=>'If the bike binds or wiring looks damaged, get it checked before riding again.','source'=>'Motor controller diagnostics'],
      'e03' => ['title'=>'Torque/Speed Sensor Fault','severity'=>'medium','description'=>'Pedal-assist sensors report invalid or no values.','what'=>'The bike can\'t reliably read pedal force or wheel speed, so assist may become weak, delayed, or disabled for safety.','causes'=>['Sensor magnet misalignment (speed sensor)','Loose sensor connector or damaged cable near the crank/wheel','Calibration drift after service or firmware update'],'symptoms'=>['Assist feels delayed or inconsistent','Speed reads 0 while moving (speed sensor issue)','Assist works only at certain pedal cadence'],'fix'=>['Check sensor magnet alignment (if applicable) and secure mounting.','Inspect connectors at the sensor and controller.','Try re-calibrating or re-booting the display/controller.','Replace sensor if intermittent readings continue.'],'rideability'=>'caution','rideabilityGuidance'=>'You can usually ride home carefully. Expect reduced or inconsistent assist and avoid busy traffic/hills.','urgency'=>'soon','urgencyGuidance'=>'Service soon if it repeats—sensor faults can leave you without assist unexpectedly.','source'=>'OEM sensor troubleshooting'],
      'e04' => ['title'=>'Controller Overtemperature','severity'=>'medium','description'=>'Controller temperature exceeded safe threshold temporarily.','what'=>'The controller is too hot to operate safely. Assist may be reduced or cut off until the temperature drops.','causes'=>['Long climbs or high assist in hot weather','Poor airflow around the controller area','Dragging brake or drivetrain load increasing current draw'],'symptoms'=>['Assist fades gradually then stops','Error appears after sustained climbs','Controller area feels very warm to the touch'],'fix'=>['Stop and allow the bike to cool down (avoid heavy loads).','Inspect for blocked airflow or damaged heatsink.','Avoid high-load climbs until diagnosis.'],'rideability'=>'caution','rideabilityGuidance'=>'You can usually ride home by reducing assist and load. Stop and cool down if the error returns.','urgency'=>'soon','urgencyGuidance'=>'If it happens frequently in normal riding, get it checked for airflow or electrical issues.','source'=>'Controller thermal protection'],
      'e05' => ['title'=>'Throttle Not Responding','severity'=>'low','description'=>'Throttle reports no input or unstable values.','what'=>'The throttle signal is missing or out of range. Many bikes disable throttle for safety when the signal is unstable.','causes'=>['Loose throttle connector','Damaged throttle cable or water ingress','Brake cut-off sensor stuck (disables throttle)'],'symptoms'=>['Throttle does nothing or feels intermittent','Assist works but throttle is disabled','Error appears when turning handlebars (cable strain)'],'fix'=>['Check throttle wiring and connector seating.','Try cleaning throttle pivot and check for binding.','Test with a different throttle if available.'],'rideability'=>'ok','rideabilityGuidance'=>'Usually safe to ride using pedal assist only. Avoid relying on throttle until fixed.','urgency'=>'info','urgencyGuidance'=>'Fix at your convenience unless it disables assist or appears with other errors.','source'=>'Throttle and user interface troubleshooting'],
      'e06' => ['title'=>'Hall Sensor Failure','severity'=>'high','description'=>'Incorrect or missing hall sensor signals from the motor.','fix'=>['Inspect motor connector and wiring to the controller.','Check for moisture or corrosion at the connector.','If available, run motor bench test at a service centre.'],'rideability'=>'stop','urgency'=>'immediate','source'=>'Motor diagnostics'],
      'e07' => ['title'=>'Display Communication Error','severity'=>'low','description'=>'Console/display cannot communicate with the controller.','fix'=>['Power cycle the bike and display.','Inspect display ribbon/connector for damage.','Try re-connecting or swapping a known-good display.'],'rideability'=>'caution','urgency'=>'soon'],
      'e08' => ['title'=>'Low Battery Voltage','severity'=>'medium','description'=>'Pack voltage below operational threshold or sudden drop detected.','fix'=>['Check battery state-of-charge and charge fully.','Inspect for poor battery contact or loose wiring.','If repeated, have battery tested for cell imbalance.'],'rideability'=>'caution','urgency'=>'soon'],
      'e09' => ['title'=>'Overvoltage Event','severity'=>'high','description'=>'Controller detected voltage above safe limit.','fix'=>['Power down immediately and avoid charging until inspected.','Check charger and battery for faults.','Contact service — overvoltage can damage electronics.'],'rideability'=>'stop','urgency'=>'immediate'],
      'e10' => ['title'=>'Brake Sensor Trigger Fault','severity'=>'low','description'=>'Brake cut-off sensor stuck or reporting incorrectly.','fix'=>['Inspect brake lever sensor and wiring.','Clean contacts and check for mechanical binding.','Replace switch if intermittent.'],'rideability'=>'ok','urgency'=>'info'],
      'e11' => ['title'=>'Speedometer Mismatch','severity'=>'low','description'=>'Speed readings differ significantly from expected values.','fix'=>['Check wheel magnet and sensor alignment.','Verify wheel circumference setting in display.'],'rideability'=>'caution','urgency'=>'soon'],
      'e12' => ['title'=>'Controller EEPROM Error','severity'=>'medium','description'=>'Controller memory read/write or configuration corruption.','fix'=>['Try a soft reset of the controller (power cycle).','If available, re-flash controller firmware with OEM tools.'],'rideability'=>'caution','urgency'=>'soon'],
      'e13' => ['title'=>'CAN Bus / External Module Error','severity'=>'medium','description'=>'Communication issue with external modules over CAN/serial.','fix'=>['Inspect CAN/serial wiring and connectors.','Check for recent module changes or aftermarket devices.'],'rideability'=>'caution','urgency'=>'soon'],
      'e14' => ['title'=>'Regenerative Braking Fault','severity'=>'low','description'=>'Regeneration subsystem reporting an error.','fix'=>['Confirm braking hardware is functioning normally.','Check firmware/settings for regen limits.'],'rideability'=>'caution','urgency'=>'info'],
      'e15' => ['title'=>'Battery Temperature Sensor Fault','severity'=>'high','description'=>'Battery temperature sensing out of range or disconnected.','fix'=>['Inspect temperature sensor lead and connector.','Avoid charging or heavy use until resolved.'],'rideability'=>'stop','urgency'=>'immediate'],
      'e16' => ['title'=>'Connector Short Circuit','severity'=>'high','description'=>'Detected short in power/charger connector area.','fix'=>['Power down immediately and inspect connectors for damage.','Do not attempt to charge until cleared by a technician.'],'rideability'=>'stop','urgency'=>'immediate'],
      'e17' => ['title'=>'Faulty Charger Detection','severity'=>'medium','description'=>'Charger presence/handshake not detected correctly.','fix'=>['Try a different known-good charger.','Inspect charging port for debris or damage.'],'rideability'=>'caution','urgency'=>'soon'],
      'e18' => ['title'=>'Motor Phase Imbalance','severity'=>'high','description'=>'Phase currents differ unexpectedly indicating wiring or motor fault.','fix'=>['Inspect motor phase wires for damage.','If present, remove wheel and bench-test the motor.'],'rideability'=>'stop','urgency'=>'immediate'],
      'e19' => ['title'=>'Controller Ground Fault','severity'=>'high','description'=>'Unusual current paths or grounding detected.','fix'=>['Inspect frame and mounting points for contact with wiring.','Stop using the bike and seek professional inspection.'],'rideability'=>'stop','urgency'=>'immediate'],
      'e20' => ['title'=>'Firmware Version Mismatch','severity'=>'low','description'=>'Controller and display versions incompatible or deprecated.','fix'=>['Check for firmware updates for display and controller.','Follow OEM upgrade instructions carefully.'],'rideability'=>'caution','urgency'=>'info'],
      'e21' => ['title'=>'Pedal Assist Calibration Error','severity'=>'low','description'=>'Calibration parameters out of expected range.','fix'=>['Run pedal-assist calibration from the display menu if available.','If not, consult the service manual.'],'rideability'=>'caution','urgency'=>'soon'],
      'e22' => ['title'=>'USB Debug Interface Active','severity'=>'low','description'=>'Controller in programming/debug mode — normal for service only.','fix'=>['Exit debug mode via OEM tool or power-cycle the system.','Avoid using the bike in this state for safety.'],'rideability'=>'caution','urgency'=>'info'],
      'e23' => ['title'=>'Low Torque Output','severity'=>'medium','description'=>'Controller limiting torque due to a safety condition or sensor fault.','fix'=>['Check torque sensor, PAS settings and wiring.','Inspect battery voltage under load.'],'rideability'=>'caution','urgency'=>'soon'],
      'e24' => ['title'=>'High Idle Current','severity'=>'medium','description'=>'Controller draws unexpected current while idle.','fix'=>['Inspect accessories and lights for shorted circuits.','Monitor current draw with diagnostic tools.'],'rideability'=>'caution','urgency'=>'soon'],
      'e25' => ['title'=>'Water Ingress Detected','severity'=>'high','description'=>'Moisture detected in controller or battery leading to faults.','fix'=>['Dry components thoroughly and inspect for corrosion.','Do not ride until system is checked by service.'],'rideability'=>'stop','urgency'=>'immediate'],
      'e26' => ['title'=>'Faulty External Sensor','severity'=>'low','description'=>'Third-party or optional sensor reports invalid data.','fix'=>['Disconnect optional sensors and test core system.','Replace or recalibrate the external sensor.'],'rideability'=>'caution','urgency'=>'info'],
      'e27' => ['title'=>'ABS / Traction Control Fault','severity'=>'medium','description'=>'Advanced stability system reports an internal error.','fix'=>['Restart the system and check wheel sensors.','If persistent, inspect ABS module wiring.'],'rideability'=>'caution','urgency'=>'soon'],
      'e28' => ['title'=>'Drive Mode Selection Error','severity'=>'low','description'=>'Requested drive mode cannot be engaged.','fix'=>['Cycle through drive modes and confirm settings.','Reset to defaults if necessary.'],'rideability'=>'caution','urgency'=>'info'],
      'e29' => ['title'=>'Persistent Fault Flag','severity'=>'medium','description'=>'Controller reports a stored persistent fault requiring clear and check.','fix'=>['Use OEM diagnostic tool to read and clear fault logs.','Investigate any logged faults before clearing.'],'rideability'=>'caution','urgency'=>'soon'],
