      'e04' => ['title'=>'6KM Walk Mode / Throttle Return Error','severity'=>'Low','description'=>'Startup or walk mode signal is abnormal.','what'=>'Controller detected an unexpected control input.','causes'=>['Button stuck','Throttle not returned','Display control issue'],'symptoms'=>['Error at startup','Walk mode issue','No assist until restart'],'fix'=>['Release controls before startup','Check buttons','Restart display'],'rideability'=>'Caution','urgency'=>'Info'],
