      'e07' => ['title'=>'Motor Hall Sensor Fault','severity'=>'High','description'=>'Hall feedback missing; commutation may fail.','what'=>'Controller cannot synchronize phase timing safely.','causes'=>['Hall wire damage','Controller fault','Motor sensor failure'],'symptoms'=>['Judder','No start','Heat buildup'],'fix'=>['Inspect hall wiring','Check motor cable','Replace failed sensor'],'rideability'=>'Stop','urgency'=>'Immediate'],
      'e08' => ['title'=>'Motor Phase Fault','severity'=>'High','description'=>'Motor phase wire signal is abnormal.','what'=>'Power wires between controller and motor may be shorted or disconnected.','causes'=>['Loose phase connector','Burned wire','Controller MOSFET fault'],'symptoms'=>['Motor vibrates','No rotation','Controller gets hot'],'fix'=>['Stop riding','Inspect phase wires','Check connectors','Service controller/motor'],'rideability'=>'Stop','urgency'=>'Immediate'],
