      'e11' => ['title'=>'Communication Send Error','severity'=>'Medium','description'=>'Display commands are not reaching controller reliably.','what'=>'Controller is not receiving expected control data.','causes'=>['Display cable issue','Controller port fault','Protocol mismatch'],'symptoms'=>['Buttons not working','Mode not changing','No assist'],'fix'=>['Reconnect display','Inspect pins','Try compatible display/controller'],'rideability'=>'Caution','urgency'=>'Soon'],
      'e12' => ['title'=>'BMS Communication Fault','severity'=>'High','description'=>'Battery management system communication failed.','what'=>'Smart battery data is unavailable.','causes'=>['Battery contacts dirty','BMS fault','Communication wire damage'],'symptoms'=>['Battery not recognised','Power loss','Charging abnormal'],'fix'=>['Clean contacts','Reseat battery','Battery diagnostic'],'rideability'=>'Stop','urgency'=>'Immediate'],
